package br.com.confirmacao.audit.application;import br.com.confirmacao.audit.domain.*;import br.com.confirmacao.audit.infrastructure.AuditLogRepository;import br.com.confirmacao.user.domain.User;import jakarta.servlet.http.HttpServletRequest;import org.springframework.data.domain.*;import org.springframework.security.core.context.SecurityContextHolder;import org.springframework.security.oauth2.server.resource.authentication.JwtAuthenticationToken;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.*;import java.util.UUID;
@Service public class AuditService{private final AuditLogRepository repo;public AuditService(AuditLogRepository r){repo=r;}@Transactional(propagation=Propagation.REQUIRES_NEW)public void record(AuditAction a,String type,UUID id,HttpServletRequest h){UUID actor=null;var auth=SecurityContextHolder.getContext().getAuthentication();if(auth instanceof JwtAuthenticationToken j)actor=parse(j.getToken().getSubject());save(actor,a,type,id,ip(h));}@Transactional(propagation=Propagation.REQUIRES_NEW)public void recordLogin(AuditAction a,User u,HttpServletRequest h){save(u==null?null:u.getId(),a,"AUTH",u==null?null:u.getId(),ip(h));}@Transactional(propagation=Propagation.REQUIRES_NEW)public void recordPasswordReset(AuditAction a,User u,HttpServletRequest h){save(u.getId(),a,"USER",u.getId(),ip(h));}@Transactional(readOnly=true)public Page<AuditLog> findAll(Pageable p){return repo.findAll(p);}private void save(UUID u,AuditAction a,String t,UUID id,String ip){repo.save(new AuditLog(u,a,t,id,ip));}private UUID parse(String v){try{return v==null?null:UUID.fromString(v);}catch(Exception e){return null;}}private String ip(HttpServletRequest r){String f=r.getHeader("X-Forwarded-For");return f!=null&&!f.isBlank()?f.split(",")[0].trim():r.getRemoteAddr();}}
